import cmath, math, random

SQ2 = 1 / math.sqrt(2)

def clean(x):
    return round(x, 3) + 0.0                      # round, and turn -0.0 into 0.0 for tidy printing

def show(state):
    return [complex(clean(complex(a).real), clean(complex(a).imag)) for a in state]

def probabilities(state):
    return [clean(abs(a) ** 2) for a in state]

def apply(gate, state):
    return [sum(gate[r][c] * state[c] for c in range(len(state))) for r in range(len(gate))]

ZERO, ONE = [1, 0], [0, 1]
H = [[SQ2, SQ2], [SQ2, -SQ2]]
X = [[0, 1], [1, 0]]
Y = [[0, -1j], [1j, 0]]
Z = [[1, 0], [0, -1]]
S_GATE = [[1, 0], [0, 1j]]
def bloch(state):
    a, b = complex(state[0]), complex(state[1])
    product = a.conjugate() * b
    return (clean(2 * product.real), clean(2 * product.imag), clean(abs(a) ** 2 - abs(b) ** 2))

plus = apply(H, ZERO)
states = {"|0>": ZERO, "|1>": ONE, "|+>": plus, "|->": apply(H, ONE), "|+i>": apply(S_GATE, plus)}
for name, state in states.items():
    print(f"{name:5} (x, y, z) = {bloch(state)}")

import cmath, math, random

SQ2 = 1 / math.sqrt(2)

def clean(x):
    return round(x, 3) + 0.0                      # round, and turn -0.0 into 0.0 for tidy printing

def show(state):
    return [complex(clean(complex(a).real), clean(complex(a).imag)) for a in state]

def probabilities(state):
    return [clean(abs(a) ** 2) for a in state]

def apply(gate, state):
    return [sum(gate[r][c] * state[c] for c in range(len(state))) for r in range(len(gate))]

ZERO, ONE = [1, 0], [0, 1]
H = [[SQ2, SQ2], [SQ2, -SQ2]]
X = [[0, 1], [1, 0]]
Y = [[0, -1j], [1j, 0]]
Z = [[1, 0], [0, -1]]
S_GATE = [[1, 0], [0, 1j]]
def dagger(M):
    return [[complex(M[c][r]).conjugate() for c in range(len(M))] for r in range(len(M[0]))]

def matmul(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]

def is_identity(M):
    return all(abs(M[i][j] - (1 if i == j else 0)) < 1e-9 for i in range(len(M)) for j in range(len(M)))

for name, gate in (("X", X), ("Y", Y), ("Z", Z), ("H", H), ("S", S_GATE)):
    print(f"{name}: unitary = {is_identity(matmul(dagger(gate), gate))!s:5} | on |0> -> {show(apply(gate, ZERO))}")

